package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentBinding;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentCompareOp;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentCompiler;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentIR;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentTelemetry;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.LongPredicateFragment;

/**
 * Builds fragment fast paths from the engine's <em>existing</em> filter implementations (fragment-fusion M1). Rather
 * than re-translating {@code ValueExpr} algebra, recognition works over the introspectable {@code NativeBooleanFilter}
 * classes — {@code CachedCompareFilter}, {@code OrderedSlotCompareFilter}, and their {@code BooleanCombinationFilter}
 * compositions — because those classes already encode the engine's exact native decision procedure (bound checks,
 * ordered-integer compares, resource identity) with its fallback boundary.
 *
 * <p>
 * Soundness notes. The recognized fragment maps unbound arguments to ERROR, which folds to reject at the filter site —
 * exactly the recognized filters' {@code checkBound} behavior — and AND/OR composition over per-operand folded booleans
 * is homomorphic to SPARQL's three-valued composition folded at the site ({@code fold(E&&x) ==
 * fold(E)&&fold(x)}), so composite recognition is exact. Negation is <em>not</em> recognized: folding is not
 * homomorphic under NOT. Anything unrecognized simply keeps today's path; anything undecidable at runtime ESCAPEs into
 * the original filter.
 */
@Experimental
final class LmdbNativeFragmentRecognizer {

	private LmdbNativeFragmentRecognizer() {
	}

	/** A compiled fragment fast path plus its per-query binding; the exact fallback stays with the caller. */
	record Recognized(LongPredicateFragment fragment, FragmentBinding binding) {
	}

	/**
	 * Attempts to build a fragment fast path for one registered filter hook. Returns null when the filter shape is not
	 * recognized; the caller keeps the ordinary scratch-row path.
	 */
	static Recognized recognize(LmdbNativeKernelBindings.FilterHook hook) {
		List<Long> constants = new ArrayList<>();
		FragmentNode node = node(hook.source.filter, hook.argSlots, constants);
		if (node == null) {
			FragmentTelemetry.DECLINED.increment();
			return null;
		}
		FragmentIR ir;
		try {
			ir = FragmentIR.predicate(node);
		} catch (RuntimeException invalid) {
			FragmentTelemetry.DECLINED.increment();
			return null;
		}
		long[] boundConstants = new long[constants.size()];
		for (int i = 0; i < boundConstants.length; i++) {
			boundConstants[i] = constants.get(i);
		}
		FragmentTelemetry.RECOGNIZED.increment();
		return new Recognized(FragmentCompiler.compilePredicate(ir),
				new FragmentBinding(boundConstants, null, null));
	}

	private static FragmentNode node(NativeBooleanFilter filter, int[] argSlots, List<Long> constants) {
		if (filter instanceof CachedCompareFilter cached) {
			// Only the bound-checking form: its unbound-means-reject coincides with ERROR folding at the site.
			if (!cached.checkBound) {
				return null;
			}
			int argument = argIndex(argSlots, cached.slot);
			if (argument < 0) {
				return null;
			}
			FragmentCompareOp op = map(cached.op);
			if (ValueIds.isOrderedInteger(cached.constant)) {
				int slot = constants.size();
				constants.add(cached.constant);
				FragmentNode argDecode = new FragmentNode.DecodeInline(new FragmentNode.Argument(argument),
						FragmentNode.DecodeInline.InlineKind.ORDERED_INTEGER);
				FragmentNode constDecode = new FragmentNode.DecodeInline(new FragmentNode.Constant(slot),
						FragmentNode.DecodeInline.InlineKind.ORDERED_INTEGER);
				return cached.constantOnLeft ? new FragmentNode.Compare(op, constDecode, argDecode)
						: new FragmentNode.Compare(op, argDecode, constDecode);
			}
			if (op == FragmentCompareOp.EQ || op == FragmentCompareOp.NE) {
				int slot = constants.size();
				constants.add(cached.constant);
				return cached.constantOnLeft
						? new FragmentNode.Compare(op, new FragmentNode.Constant(slot),
								new FragmentNode.Argument(argument))
						: new FragmentNode.Compare(op, new FragmentNode.Argument(argument),
								new FragmentNode.Constant(slot));
			}
			// an order comparison against a non-ordered constant has no native fast path worth taking
			return null;
		}
		if (filter instanceof OrderedSlotCompareFilter ordered) {
			if (!ordered.checkLeftBound || !ordered.checkRightBound) {
				return null;
			}
			int left = argIndex(argSlots, ordered.leftSlot);
			int right = argIndex(argSlots, ordered.rightSlot);
			if (left < 0 || right < 0) {
				return null;
			}
			return new FragmentNode.Compare(map(ordered.op), new FragmentNode.Argument(left),
					new FragmentNode.Argument(right));
		}
		if (filter instanceof BooleanCombinationFilter combination) {
			FragmentNode left = node(combination.left, argSlots, constants);
			if (left == null) {
				return null;
			}
			FragmentNode right = node(combination.right, argSlots, constants);
			if (right == null) {
				return null;
			}
			return combination.conjunction ? new FragmentNode.BooleanAnd(left, right)
					: new FragmentNode.BooleanOr(left, right);
		}
		return null;
	}

	private static int argIndex(int[] argSlots, int slot) {
		for (int i = 0; i < argSlots.length && i < 3; i++) {
			if (argSlots[i] == slot) {
				return i;
			}
		}
		return -1;
	}

	private static FragmentCompareOp map(Compare.CompareOp op) {
		switch (op) {
		case EQ:
			return FragmentCompareOp.EQ;
		case NE:
			return FragmentCompareOp.NE;
		case LT:
			return FragmentCompareOp.LT;
		case LE:
			return FragmentCompareOp.LE;
		case GT:
			return FragmentCompareOp.GT;
		default:
			return FragmentCompareOp.GE;
		}
	}
}
